import csv
TARGET_AREAS = ['Portland-Vancouver-Hillsboro, OR-WA', 'Wichita, KS', 'San Diego-Carlsbad, CA']
THRESHOLD = 4.4
good_years = []
for year in range(2000, 2011):
    filename = f'daily_42101_{year}.csv'
    try:
        daily_max = {area: {} for area in TARGET_AREAS}
        with open(filename, 'r', encoding='utf-8', errors='ignore') as f:
            r = csv.DictReader(f)
            for row in r:
                cbsa = row.get('CBSA Name', '')
                if cbsa in daily_max:
                    date = row.get('Date Local', '')
                    try:
                        co_val = float(row.get('Arithmetic Mean', 0))
                        if date not in daily_max[cbsa] or co_val > daily_max[cbsa][date]:
                            daily_max[cbsa][date] = co_val
                    except: pass
        max_vals = {area: max(daily_max[area].values()) if daily_max[area] else 0 for area in TARGET_AREAS}
        if all(v <= THRESHOLD for v in max_vals.values()):
            good_years.append(year)
            print(f'{year}: PASS - {max_vals}')
        else:
            exceeders = {k:v for k,v in max_vals.items() if v > THRESHOLD}
            print(f'{year}: FAIL - max: {max_vals}')
    except FileNotFoundError:
        print(f'{year}: FILE NOT FOUND')
print(f'\nGOOD YEARS: {good_years}')
"
